let probeResults = {};
async function runProbe(name, fn) {
  try { probeResults[name] = {ok:true, value: await fn()}; }
  catch (e) { probeResults[name] = {ok:false, message: e && e.message ? e.message : String(e)}; }
}
await runProbe("ax_summary", async () => { let a = await cua.getApp("Preview"); return await a.getAXState({disableDiffing:true}); });
await runProbe("main_window_click", async () => { let a = await cua.getApp("Preview"); await a.click(0); return "clicked"; });
await runProbe("menu_or_dropdown", async () => { let a = await cua.getApp("Preview"); await a.click(0); return "opened"; });
await runProbe("shortcut", async () => { let a = await cua.getApp("Preview"); await a.pressKey("Command+O"); return "delivered"; });
nodeRepl.write(probeResults);

